<style scoped lang="scss" src="./top-donor-block.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import { has } from "../../util/has";
import Icon from "../../components/icon/icon";
import {
  TopDonorMode,
  TopDonorModeValues,
  TopDonorTitle,
  IconBackground,
  ModeToIcon
} from "../top-donor-block/top-donor-block.constants";

@Component({
  components: {
    Icon
  }
})
export default class TopDonorBlock extends Vue {
  @Prop({ type: String, default: "" }) firstName;
  @Prop({ type: String, default: "" }) lastName;
  @Prop({ type: String, default: "" }) image;
  @Prop({
    type: String,
    default: TopDonorMode.MOST_RAISED,
    validator: has(TopDonorModeValues)
  })
  mode;

  get title() {
    return TopDonorTitle[this.mode];
  }

  get iconShape() {
    return ModeToIcon[this.mode];
  }

  get iconBackground() {
    return IconBackground[this.mode];
  }

  get fullName() {
    return `${this.firstName} ${this.lastName[0]}.`;
  }
}
</script>

<template>
  <div class="TopDonorBlock">
    <div class="TopDonorBlock__Title">{{ title }}</div>
    <div class="TopDonorBlock__Background">
      <div class="TopDonorBlock__Name">{{ fullName }}</div>
    </div>
    <div class="TopDonorBlock__Images">
      <div
        class="TopDonorBlock__Profile"
        v-bind:style="{ backgroundImage: `url(${image})` }"
      />
      <div :class="['TopDonorBlock__Icon', iconBackground]">
        <Icon :shape="iconShape" :size="14" :color="'#ffffff'" />
      </div>
    </div>
  </div>
</template>
